/**
 * Alpine.js minimal offline runtime stub.
 * Provides x-data, x-init, x-model, @click, @change, :class, :style, x-text, x-show, x-for, template x-if.
 * This enables the reactive HTML template from the spec to work standalone offline without external Alpine.
 */
(() => {
  if (window.Alpine) return;

  const Alpine = {
    version: "3.x-offline-compact",
    start() {
      document.addEventListener("DOMContentLoaded", () => {
        Alpine.initTree(document.body);
      });
      if (document.readyState === "complete" || document.readyState === "interactive") {
        Alpine.initTree(document.body);
      }
    },
    initTree(el) {
      const roots = el.querySelectorAll("[x-data]");
      roots.forEach((root) => Alpine.initComponent(root));
    },
    initComponent(root) {
      if (root._alpineComponent) return;
      const expr = root.getAttribute("x-data");
      let data = {};
      try {
        const fn = new Function(`return (${expr || "{}"})`);
        data = fn();
      } catch (e) {
        console.error("Failed to parse x-data:", expr, e);
      }

      const reactiveData = Alpine.createObservable(data, () => {
        Alpine.updateBindings(root, reactiveData);
      });
      root._alpineComponent = reactiveData;

      // Handle x-init
      const initExpr = root.getAttribute("x-init");
      if (initExpr) {
        try {
          const fn = new Function(`with(this) { return (${initExpr}); }`);
          fn.call(reactiveData);
        } catch (e) {
          console.error("Failed to execute x-init:", initExpr, e);
        }
      } else if (typeof reactiveData.init === "function") {
        reactiveData.init();
      }

      Alpine.bindEvents(root, reactiveData);
      Alpine.updateBindings(root, reactiveData);
    },
    createObservable(target, onChange) {
      const handler = {
        get(obj, prop) {
          const val = obj[prop];
          if (val && typeof val === "object" && !val._isProxy) {
            return new Proxy(val, handler);
          }
          return val;
        },
        set(obj, prop, value) {
          const old = obj[prop];
          obj[prop] = value;
          if (old !== value && onChange) {
            onChange();
          }
          return true;
        }
      };
      const proxy = new Proxy(target, handler);
      target._isProxy = true;
      return proxy;
    },
    bindEvents(container, scope) {
      const clickEls = container.querySelectorAll("[\\@click]");
      clickEls.forEach((el) => {
        if (el._hasAlpineClick) return;
        el._hasAlpineClick = true;
        const expr = el.getAttribute("@click");
        el.addEventListener("click", (evt) => {
          try {
            const fn = new Function("$event", `with(this) { return (${expr}); }`);
            fn.call(scope, evt);
          } catch (err) {
            console.error("Error evaluating @click:", expr, err);
          }
        });
      });

      const changeEls = container.querySelectorAll("[\\@change]");
      changeEls.forEach((el) => {
        if (el._hasAlpineChange) return;
        el._hasAlpineChange = true;
        const expr = el.getAttribute("@change");
        el.addEventListener("change", (evt) => {
          try {
            const fn = new Function("$event", `with(this) { return (${expr}); }`);
            fn.call(scope, evt);
          } catch (err) {
            console.error("Error evaluating @change:", expr, err);
          }
        });
      });

      const modelEls = container.querySelectorAll("[x-model]");
      modelEls.forEach((el) => {
        if (el._hasAlpineModel) return;
        el._hasAlpineModel = true;
        const key = el.getAttribute("x-model");
        el.addEventListener("input", () => {
          scope[key] = el.value;
        });
        el.addEventListener("change", () => {
          scope[key] = el.value;
        });
      });
    },
    updateBindings(container, scope) {
      // x-model sync from scope
      const modelEls = container.querySelectorAll("[x-model]");
      modelEls.forEach((el) => {
        const key = el.getAttribute("x-model");
        if (scope[key] !== undefined && el.value !== scope[key]) {
          el.value = scope[key];
        }
      });

      // x-text
      const textEls = container.querySelectorAll("[x-text]");
      textEls.forEach((el) => {
        const expr = el.getAttribute("x-text");
        try {
          const fn = new Function(`with(this) { return (${expr}); }`);
          const val = fn.call(scope);
          el.textContent = val !== undefined && val !== null ? val : "";
        } catch (e) {
          // ignore transient render errors during data fetching
        }
      });

      // :class
      const classEls = container.querySelectorAll("[\\:class]");
      classEls.forEach((el) => {
        const expr = el.getAttribute(":class");
        try {
          const fn = new Function(`with(this) { return (${expr}); }`);
          const val = fn.call(scope);
          if (typeof val === "string") {
            const originalClasses = (el.dataset.origClass || el.className).split(" ");
            el.dataset.origClass = el.dataset.origClass || el.className;
            el.className = `${el.dataset.origClass} ${val}`.trim();
          }
        } catch (e) {}
      });

      // :style
      const styleEls = container.querySelectorAll("[\\:style]");
      styleEls.forEach((el) => {
        const expr = el.getAttribute(":style");
        try {
          const fn = new Function(`with(this) { return (${expr}); }`);
          const val = fn.call(scope);
          if (typeof val === "string") {
            el.setAttribute("style", val);
          }
        } catch (e) {}
      });

      // x-show
      const showEls = container.querySelectorAll("[x-show]");
      showEls.forEach((el) => {
        const expr = el.getAttribute("x-show");
        try {
          const fn = new Function(`with(this) { return !!(${expr}); }`);
          const visible = fn.call(scope);
          el.style.display = visible ? "" : "none";
        } catch (e) {}
      });
    }
  };

  window.Alpine = Alpine;
  Alpine.start();
})();
